import math, random, subprocess, sys, os
from decimal import Decimal, ROUND_HALF_EVEN

MINE = "/tmp/build/adv_ds04"
SHIP = "/workspace/Homework/DS04_IslandLake"

def run(cp, inp):
    p = subprocess.run(["timeout","60","java","-cp",cp,"Main"], input=inp,
                       capture_output=True, text=True)
    return p.returncode, p.stdout, p.stderr

def dist(a,b):
    return math.sqrt(math.pow(a[0]-b[0],2)+math.pow(a[1]-b[1],2))

def expected(pts):
    """Replicate reference semantics: filter 10<=d<=1000, MSF via Kruskal, 'oh!' if
    some vertex has no candidate edge. Independently also compute Prim MSF weight."""
    C=len(pts)
    edges=[]
    linked=[False]*C
    for i in range(C):
        for j in range(i+1,C):
            d=dist(pts[i],pts[j])
            if d<=1000.0 and d>=10.0:
                edges.append((d,i,j)); linked[i]=True; linked[j]=True
    if C>0 and not all(linked):
        return "oh!", None, None
    # Kruskal
    edges_sorted=sorted(edges, key=lambda e:e[0])   # stable, like TimSort on weight
    par=list(range(C))
    def find(x):
        while par[x]!=x: x=par[x]
        return x
    total=0.0; acc=[]
    for d,i,j in edges_sorted:
        ri,rj=find(i),find(j)
        if ri==rj: continue
        par[ri]=rj; total+=d; acc.append((i,j,d))
    # Prim (independent) minimum spanning forest over same filtered graph
    adj={i:{} for i in range(C)}
    for d,i,j in edges:
        if d < adj[i].get(j, float('inf')):
            adj[i][j]=d; adj[j][i]=d
    seen=[False]*C; prim=0.0; prim_edges=0; comps=0
    for s in range(C):
        if seen[s]: continue
        comps+=1
        seen[s]=True; frontier=dict(adj[s])
        while frontier:
            v=min(frontier, key=lambda k: frontier[k])
            w=frontier.pop(v)
            if seen[v]: continue
            seen[v]=True; prim+=w; prim_edges+=1
            for u,wu in adj[v].items():
                if not seen[u] and wu<frontier.get(u,float('inf')):
                    frontier[u]=wu
    return None, (total, len(acc)), (prim, prim_edges, comps)

def fmt(v):
    # DecimalFormat("0.0") -> HALF_EVEN on the exact double
    return str(Decimal(v).quantize(Decimal('0.1'), rounding=ROUND_HALF_EVEN))

def check(cases, label):
    inp="".join(str(len(c[0]))+"\n"+"".join(f"{x} {y}\n" for x,y in c[0]) for c in [(c,) for c in cases])
    inp=f"{len(cases)}\n"+inp+"0\n"
    rc1,o1,e1=run(MINE,inp); rc2,o2,e2=run(SHIP,inp)
    bad=[]
    if (rc1,o1)!=(rc2,o2):
        bad.append(f"MINE vs SHIPPED DIVERGE rc={rc1}/{rc2}\nMINE:\n{o1}{e1}\nSHIP:\n{o2}{e2}")
    lines=o1.strip().split("\n") if o1.strip() else []
    if len(lines)!=len(cases):
        bad.append(f"line count {len(lines)} != cases {len(cases)}; stderr={e1[:400]}")
        return bad,o1
    for k,(pts,line) in enumerate(zip(cases,lines)):
        oh,kr,pr=expected(pts)
        if oh:
            if line!="oh!": bad.append(f"case{k} expected oh! got {line} pts={pts}")
            continue
        if line=="oh!":
            bad.append(f"case{k} unexpected oh! pts={pts}"); continue
        got=float(line)
        ktot,kedges=kr; ptot,pedges,comps=pr
        if abs(ktot-ptot)>1e-6*max(1.0,abs(ptot)):
            bad.append(f"case{k} KRUSKAL!=PRIM {ktot} vs {ptot} pts={pts}")
        if kedges!=pedges or kedges!=len(pts)-comps:
            bad.append(f"case{k} edgecount {kedges}/{pedges} V={len(pts)} comps={comps}")
        if abs(got-ptot*100.0)>0.06:
            bad.append(f"case{k} JAVA={got} EXPECTED={ptot*100.0} pts={pts}")
        if fmt(ptot*100.0)!=line:
            bad.append(f"case{k} FORMAT java={line} py={fmt(ptot*100.0)} raw={ptot*100.0!r}")
    return bad,o1

